def check_pid(pid):
 try:os.kill(pid,0);return {'pid':pid,'absent':False,'errno':None}
 except OSError as e:return {'pid':pid,'absent':e.errno==errno.ESRCH,'errno':errno.errorcode.get(e.errno),'errnoNumber':e.errno}
